exercises.tests:
def test_default_timeout():
    result = make_request("GET", "/users")
    assert result == {"method": "GET", "url": "/users", "timeout": 30}, "timeout по умолчанию должен быть 30"


def test_keyword_timeout():
    result = make_request("GET", "/users", timeout=5)
    assert result == {"method": "GET", "url": "/users", "timeout": 5}, "timeout можно передать по имени"


def test_positional_timeout_raises_type_error():
    try:
        make_request("GET", "/users", 5)
        raised = False
    except TypeError:
        raised = True
    assert raised, "timeout объявлен после одинокой * — его нельзя передать позиционным третьим аргументом, должен быть TypeError"
